17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (dailyRegistrationLimitReached()) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (cityAtCapacity(owner.getCity())) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (owner.getRegistrationDate() == null) {
117	            owner.setRegistrationDate(LocalDate.now());
118	        }
119	        owner.setCity(resolveCity(owner.getCity()));
120	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
121	        owner.setMembershipNumber(membershipNumber);
122	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
123	        owner.setMembershipTier(membershipTierFor(membershipNumber));
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    /**
132	     * The maximum number of owners that may be registered on any single day (by registration date).
133	     */
134	    private static final long MAX_OWNERS_PER_DAY = 20;
135	
136	    /**
137	     * Determines whether the maximum number of owners for the current day has already been reached.
138	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
139	     * carry today's registration date no further owners may be created today.
140	     *
141	     * @return {@code true} if today's registration limit has been reached
142	     */
143	    private boolean dailyRegistrationLimitReached() {
144	        LocalDate today = LocalDate.now();
145	        long registeredToday = this.clinicService.findAllOwners().stream()
146	            .filter(existing -> today.equals(existing.getRegistrationDate()))
147	            .count();
148	        return registeredToday >= MAX_OWNERS_PER_DAY;
149	    }
150	
151	    /**
152	     * The maximum number of owners that may be registered in any single city.
153	     */
154	    private static final long MAX_OWNERS_PER_CITY = 8;
155	
156	    /**
157	     * Determines whether the given city has already reached its capacity of
158	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
159	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
160	     *
161	     * @param city the raw city supplied for the owner being created, may be {@code null}
162	     * @return {@code true} if the city already contains the maximum number of owners
163	     */
164	    private boolean cityAtCapacity(String city) {
165	        if (city == null) {
166	            return false;
167	        }
168	        long ownersInCity = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
170	            .count();
171	        return ownersInCity >= MAX_OWNERS_PER_CITY;
172	    }
173	
174	    /**
175	     * Resolves the city to store for a newly created owner. If another owner is already stored in
176	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
177	     * city name is reused so that a single city is always represented consistently. Otherwise the
178	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
179	     *
180	     * @param city the raw city supplied for the owner being created, may be {@code null}
181	     * @return the city to store, or {@code null} if {@code city} is {@code null}
182	     */
183	    private String resolveCity(String city) {
184	        if (city == null) {
185	            return null;
186	        }
187	        return this.clinicService.findAllOwners().stream()
188	            .map(Owner::getCity)
189	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
190	            .findFirst()
191	            .orElseGet(() -> titleCase(city));
192	    }
193	
194	    /**
195	     * Title-cases a value so that the first letter of every whitespace-separated word is
196	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
197	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
198	     * {@code "London"}.
199	     *
200	     * @param value the raw value, may be {@code null}
201	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
202	     */
203	    private static String titleCase(String value) {
204	        if (value == null) {
205	            return null;
206	        }
207	        StringBuilder result = new StringBuilder(value.length());
208	        boolean startOfWord = true;
209	        for (int i = 0; i < value.length(); i++) {
210	            char c = value.charAt(i);
211	            if (Character.isWhitespace(c)) {
212	                startOfWord = true;
213	                result.append(c);
214	            } else {
215	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
216	                startOfWord = false;
217	            }
218	        }
219	        return result.toString();
220	    }
221	
222	    /**
223	     * Builds the customer code for a newly created owner in the given city, formatted as
224	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
225	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
226	     * count of existing owners in the city ignores letter case.
227	     *
228	     * @param city the city of the owner being created
229	     * @return the assigned customer code
230	     */
231	    private String nextCustomerCode(String city) {
232	        long ownersInCity = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
234	            .count();
235	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
236	    }
237	
238	    /**
239	     * The maximum membership number that still qualifies an owner for the founding tier. The
240	     * first {@value #MAX_FOUNDING_MEMBERS} owners ever created are founding members.
241	     */
242	    private static final int MAX_FOUNDING_MEMBERS = 100;
243	
244	    /**
245	     * Resolves the membership tier for a newly created owner from its sequential membership
246	     * number. The first {@value #MAX_FOUNDING_MEMBERS} owners ever created are {@code FOUNDING};
247	     * every later owner is {@code STANDARD}.
248	     *
249	     * @param membershipNumber the owner's sequential membership number
250	     * @return {@code "FOUNDING"} or {@code "STANDARD"}
251	     */
252	    private static String membershipTierFor(int membershipNumber) {
253	        return membershipNumber <= MAX_FOUNDING_MEMBERS ? "FOUNDING" : "STANDARD";
254	    }
255	
256	    /**
257	     * Determines whether an owner already exists using the same telephone number.
258	     * Comparison ignores letter case and surrounding or repeated whitespace.
259	     *
260	     * @param owner the candidate owner to check
261	     * @return {@code true} if any other owner with the same telephone is already stored
262	     */
263	    private boolean ownerAlreadyExists(Owner owner) {
264	        String telephone = normalizeTelephone(owner.getTelephone());
265	        return this.clinicService.findAllOwners().stream()
266	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
267	    }
268	
269	    /**
270	     * Normalizes a telephone number to digits only, stripping spaces, dashes and
271	     * parentheses (any non-digit character). This is the canonical stored form and is
272	     * used for the telephone-uniqueness check, so {@code "(613) 555-0100"} and
273	     * {@code "6135550100"} are treated as the same number.
274	     *
275	     * @param telephone the raw telephone value, may be {@code null}
276	     * @return the digits-only value, or {@code null} if {@code telephone} is {@code null}
277	     */
278	    private static String normalizeTelephone(String telephone) {
279	        if (telephone == null) {
280	            return null;
281	        }
282	        return telephone.replaceAll("[^0-9]", "");
283	    }
284	
285	    /**
286	     * Determines whether another owner already uses the same email address.
287	     * Owners without an email are ignored, so a missing email never conflicts.
288	     * Comparison ignores letter case and surrounding or repeated whitespace.
289	     *
290	     * @param owner the candidate owner to check
291	     * @return {@code true} if the candidate supplies an email already used by a stored owner
292	     */
293	    private boolean emailAlreadyExists(Owner owner) {
294	        String email = normalize(owner.getEmail());
295	        if (email == null || email.isEmpty()) {
296	            return false;
297	        }
298	        return this.clinicService.findAllOwners().stream()
299	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
300	    }
301	
302	    /**
303	     * Normalizes a value for duplicate detection so that comparisons ignore letter
304	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
305	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
306	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
307	     * both normalize to {@code "john smith"}.
308	     *
309	     * @param value the raw value, may be {@code null}
310	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
311	     */
312	    private static String normalize(String value) {
313	        if (value == null) {
314	            return null;
315	        }
316	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
322	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
323	        if (currentOwner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        currentOwner.setAddress(ownerFieldsDto.getAddress());
327	        currentOwner.setCity(ownerFieldsDto.getCity());
328	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
329	        currentOwner.setLastName(ownerFieldsDto.getLastName());
330	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
331	        this.clinicService.saveOwner(currentOwner);
332	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
333	    }
334	
335	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
336	    @Transactional
337	    @Override
338	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
339	        Owner owner = this.clinicService.findOwnerById(ownerId);
340	        if (owner == null) {
341	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	        }
343	        this.clinicService.deleteOwner(owner);
344	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
345	    }
346	
347	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
348	    @Override
349	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
350	        Owner owner = this.clinicService.findOwnerById(ownerId);
351	        if (owner == null) {
352	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
353	        }
354	        HttpHeaders headers = new HttpHeaders();
355	        Pet pet = petMapper.toPet(petFieldsDto);
356	        owner.setId(ownerId);
357	        pet.setOwner(owner);
358	        pet.getType().setName(null);
359	        this.clinicService.savePet(pet);
360	        PetDto petDto = petMapper.toPetDto(pet);
361	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
362	            .buildAndExpand(pet.getId()).toUri());
363	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
364	    }
365	
366	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
367	    @Override
368	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
369	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
370	        if (currentOwner != null) {
371	            Pet currentPet = this.clinicService.findPetById(petId);
372	            if (currentPet != null) {
373	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
374	                currentPet.setName(petFieldsDto.getName());
375	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
376	                this.clinicService.savePet(currentPet);
377	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
378	            }
379	        }
380	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
386	        HttpHeaders headers = new HttpHeaders();
387	        Visit visit = visitMapper.toVisit(visitFieldsDto);
388	        Pet pet = new Pet();
389	        pet.setId(petId);
390	        visit.setPet(pet);
391	        this.clinicService.saveVisit(visit);
392	        VisitDto visitDto = visitMapper.toVisitDto(visit);
393	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
394	            .buildAndExpand(visit.getId()).toUri());
395	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
396	    }
397	
398	
399	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
400	    @Override
401	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
402	        Owner owner = this.clinicService.findOwnerById(ownerId);
403	        if (owner != null) {
404	            Pet pet = owner.getPet(petId);
405	            if (pet != null) {
406	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
407	            }
408	        }
409	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
410	    }
411	}
